class TopVotedCandidate {
    vector<int> times;
    vector<int> leaders;
public:
    TopVotedCandidate(vector<int>& persons, vector<int>& times) {
        this->times = times;
        int n = persons.size();
        leaders.resize(n);
        vector<int> count(n, 0);
        int maxCount = 0;
        int leader = 0;
        for (int i = 0; i < n; i++) {
            int p = persons[i];
            count[p]++;
            if (count[p] >= maxCount) {
                maxCount = count[p];
                leader = p;
            }
            leaders[i] = leader;
        }
    }

    int q(int t) {
        int idx = upper_bound(times.begin(), times.end(), t) - times.begin() - 1;
        return leaders[idx];
    }
};
